export type Status = "open" | "done";

export interface Task {
  id: number;
  title: string;
  status: Status;
  tags: string[];
}

export interface ListOptions {
  /** Keep only tasks carrying this tag. */
  tag?: string;
  /** Keep only tasks with this status. */
  status?: Status;
}

/** Returns the matching tasks ordered by id. */
export function listTasks(tasks: Task[], options: ListOptions = {}): Task[] {
  return tasks
    .filter((task) => options.tag === undefined || task.tags.includes(options.tag))
    .filter((task) => options.status === undefined || task.status === options.status)
    .sort((a, b) => a.id - b.id);
}

import assert from "node:assert/strict";
import { test } from "node:test";
import { listTasks, type Task } from "../src/tasks.ts";

const tasks: Task[] = [
  { id: 2, title: "b", status: "open", tags: ["x"] },
  { id: 1, title: "a", status: "done", tags: ["x"] },
];

test("filters by status", () => {
  assert.deepEqual(listTasks(tasks, { status: "open" }).map((task) => task.id), [2]);
});
